//! Standalone proper-ring face adapter. Not full Python Mesh API.
use crate::{owner::{JournalOwner,Transaction},owner_budget::{OwnerBudget,Kind,Lease}};
use ingetrazo_core::mesh::{Mesh,MeshFace};use glam::DVec3;use std::collections::HashMap;
struct Draft{face:MeshFace,edges:Vec<usize>}
pub struct FaceTransaction{edge:Transaction,drafts:Vec<Draft>,base_faces:usize,base_edges:usize,charge:Lease,budget:OwnerBudget,failed:bool,corners:usize}
struct Command{base_faces:usize,base_edges:usize,faces:Vec<MeshFace>,incidence:Vec<(usize,Vec<usize>)>,_charge:Lease}
pub struct FaceOwner{owner:JournalOwner,undo:Vec<Command>,redo:Vec<Command>}
impl FaceOwner{
 pub fn new(mesh:Mesh)->Result<Self,String>{Ok(Self{owner:JournalOwner::new(mesh)?,undo:vec![],redo:vec![]})}
 pub fn mesh(&self)->&Mesh{self.owner.mesh()}
 pub fn budget(&self)->OwnerBudget{self.owner.budget()}
 pub fn history_counts(&self)->(usize,usize){(self.undo.len(),self.redo.len())}
 pub fn begin(&self)->Result<FaceTransaction,String>{Ok(FaceTransaction{edge:self.owner.try_begin()?,drafts:vec![],base_faces:self.mesh().faces.len(),base_edges:self.mesh().edges.len(),charge:self.budget().reserve(Kind::Staging,0)?,budget:self.budget(),failed:false,corners:0})}
 pub fn commit(&mut self,mut t:FaceTransaction)->Result<bool,String>{
  if t.failed||t.edge.journal.admission_failed{return Err("Face transaction refused; staged work discarded".into());}if t.drafts.is_empty(){return Ok(false);}
  if t.base_faces!=self.mesh().faces.len()||t.base_edges!=self.mesh().edges.len(){return Err("Stale face transaction".into());}
  let prep=self.budget().reserve(Kind::Preparation,face_bound(t.corners,t.drafts.len())?)?;
  let mut faces=Vec::new();faces.try_reserve_exact(t.drafts.len()).map_err(|_|"Face publication records refused")?;
  let mut incidence=HashMap::<usize,Vec<usize>>::new();incidence.try_reserve(t.corners).map_err(|_|"Face incidence planning refused")?;
  for (offset,draft) in t.drafts.into_iter().enumerate(){let fid=t.base_faces.checked_add(offset).ok_or("Face extent overflow")?;for eid in draft.edges{let list=incidence.entry(eid).or_default();list.try_reserve(1).map_err(|_|"Face incidence planning refused")?;list.push(fid);}faces.push(draft.face);}
  let saved=copy_faces(&faces)?;let mut radial=Vec::new();radial.try_reserve_exact(incidence.len()).map_err(|_|"Face radial history refused")?;for item in incidence{radial.push(item);}radial.sort_unstable_by_key(|x|x.0);
  let bytes=face_payload(&saved,&radial)?;let charge=self.budget().reserve(Kind::History,bytes)?;
  self.undo.try_reserve(1).map_err(|_|"Face history refused")?;
  {let (storage,edges)=self.owner.face_storage();storage.try_reserve(faces.len()).map_err(|_|"Live face reservation refused")?;for (eid,ids) in &radial{if *eid<t.base_edges{edges[*eid].faces.try_reserve(ids.len()).map_err(|_|"Live radial reservation refused")?;}}}
  // New edge radial vectors are reserved after private edge publication only
  // if preprepared storage is attached; prepare all new vectors here instead.
  let edge_total=t.base_edges.checked_add(t.edge.journal.added_edges.len()).ok_or("Edge extent overflow")?;
  let radial_bytes=(edge_total-t.base_edges).checked_mul(std::mem::size_of::<Vec<usize>>()).and_then(|n|radial.iter().filter(|x|x.0>=t.base_edges).try_fold(n,|n,x|x.1.len().checked_mul(std::mem::size_of::<usize>()).and_then(|bytes|n.checked_add(bytes)))).ok_or("New radial byte overflow")?;let _radial_charge=self.budget().reserve(Kind::Preparation,radial_bytes).map_err(|e|format!("New radial preparation: {e}"))?;let mut prepared_new=Vec::new();prepared_new.try_reserve_exact(edge_total-t.base_edges).map_err(|_|"New radial records refused")?;
  for eid in t.base_edges..edge_total{let ids=radial.binary_search_by_key(&eid,|x|x.0).ok().map(|i|&radial[i].1[..]).unwrap_or(&[]);let mut copy=Vec::new();copy.try_reserve_exact(ids.len()).map_err(|_|"New radial reservation refused")?;copy.extend_from_slice(ids);prepared_new.push(copy);}
  t.edge.force_command=true;if !self.owner.commit(t.edge)?{return Err("Face/edge publication mismatch".into());}
  {let(storage,edges)=self.owner.face_storage();for (eid,ids) in &radial{if *eid<t.base_edges{edges[*eid].faces.extend(ids);}}for (offset,ids) in prepared_new.into_iter().enumerate(){edges[t.base_edges+offset].faces=ids;}storage.extend(faces);}
  self.redo.clear();self.undo.push(Command{base_faces:t.base_faces,base_edges:t.base_edges,faces:saved,incidence:radial,_charge:charge});drop(prep);Ok(true)
 }
 pub fn undo(&mut self)->Result<bool,String>{let Some(command)=self.undo.last()else{return Ok(false)};self.redo.try_reserve(1).map_err(|_|"Face redo history refused")?;
  // Edge owner performs all fallible preparation before changing records.
  if !self.owner.undo()?{return Err("Face/edge undo mismatch".into());}let command=self.undo.pop().unwrap();let (faces,edges)=self.owner.face_storage();faces.truncate(command.base_faces);for (eid,_) in &command.incidence{if *eid<command.base_edges{edges[*eid].faces.retain(|&fid|fid<command.base_faces);}}self.redo.push(command);Ok(true)
 }
 pub fn redo(&mut self)->Result<bool,String>{let Some(command)=self.redo.last()else{return Ok(false)};let prep=self.budget().reserve(Kind::Preparation,face_bound(command.faces.iter().map(|f|f.vertices.len()+f.holes.iter().map(Vec::len).sum::<usize>()).sum(),command.faces.len())?)?;let copied=copy_faces(&command.faces)?;let mut radial=Vec::new();radial.try_reserve_exact(command.incidence.len()).map_err(|_|"Redo radial refused")?;for (eid,ids) in &command.incidence{let mut c=Vec::new();c.try_reserve_exact(ids.len()).map_err(|_|"Redo radial refused")?;c.extend_from_slice(ids);radial.push((*eid,c));}
  self.undo.try_reserve(1).map_err(|_|"Face undo history refused")?;{let(faces,edges)=self.owner.face_storage();faces.try_reserve(copied.len()).map_err(|_|"Redo face reservation refused")?;for(eid,ids)in &radial{if *eid<command.base_edges{edges[*eid].faces.try_reserve(ids.len()).map_err(|_|"Redo existing radial refused")?;}}}
  if !self.owner.redo()?{return Err("Face/edge redo mismatch".into());}let command=self.redo.pop().unwrap();{let(faces,edges)=self.owner.face_storage();for(eid,ids)in radial{if eid<command.base_edges{edges[eid].faces.extend(ids);}else{edges[eid].faces=ids;}}faces.extend(copied);}self.undo.push(command);drop(prep);Ok(true)
 }
}
impl FaceTransaction{
 pub fn abort(&mut self){self.failed=true;}
 pub fn add_face(&mut self,outer:&[DVec3],holes:&[Vec<DVec3>])->Result<usize,String>{let result=self.stage_face(outer,holes);if result.is_err(){self.failed=true;}result}
 fn stage_face(&mut self,outer:&[DVec3],holes:&[Vec<DVec3>])->Result<usize,String>{if self.failed{return Err("Face transaction previously refused".into());}
  let count=outer.len().checked_add(holes.iter().try_fold(0usize,|n,h|n.checked_add(h.len())).ok_or("Face corner overflow")?).ok_or("Face corner overflow")?;let next=self.corners.checked_add(count).ok_or("Face corner overflow")?;self.charge.resize(face_bound(next,self.drafts.len().checked_add(1).ok_or("Face extent overflow")?)?)?;
  let filtered=if holes.len()>1{crate::source_holes::maximal(holes)?.0}else{let mut all=Vec::new();all.try_reserve_exact(holes.len()).map_err(|_|"Hole filter index refused")?;all.extend(0..holes.len());all};
  let mut rings=Vec::new();rings.try_reserve_exact(1+filtered.len()).map_err(|_|"Face rings refused")?;
  for ring in std::iter::once(outer).chain(filtered.iter().map(|&i|&holes[i][..])){let mut ids=Vec::new();ids.try_reserve_exact(ring.len()).map_err(|_|"Face vertex ring refused")?;for &p in ring{ids.push(self.edge.journal.stage_vertex(p)?);}rings.push(ids);}
  let mut boundary=Vec::new();boundary.try_reserve_exact(count).map_err(|_|"Face boundary refused")?;for ring in &rings{for i in 0..ring.len(){boundary.push(self.edge.journal.link_vertices(ring[i],ring[(i+1)%ring.len()])?.0);}}
  let outer=rings.remove(0);let mut face=MeshFace::new(outer);face.holes=rings;self.drafts.try_reserve(1).map_err(|_|"Face staging refused")?;let id=self.base_faces.checked_add(self.drafts.len()).ok_or("Face extent overflow")?;self.drafts.push(Draft{face,edges:boundary});self.corners=next;Ok(id)
 }
 pub fn extrude_geometry(&mut self,outline:&[[f64;2]],z0:f64,z1:f64)->Result<(),String>{let result=(||{let helper_bytes=outline.len().checked_mul(3*std::mem::size_of::<DVec3>()).ok_or("Extrude helper extent overflow")?;let _prep=self.budget.reserve(Kind::Preparation,helper_bytes)?;let mut lo=Vec::new();let mut hi=Vec::new();let mut reverse=Vec::new();lo.try_reserve_exact(outline.len()).map_err(|_|"Extrude lower ring refused")?;hi.try_reserve_exact(outline.len()).map_err(|_|"Extrude upper ring refused")?;reverse.try_reserve_exact(outline.len()).map_err(|_|"Extrude reversed ring refused")?;for p in outline{lo.push(DVec3::new(p[0],p[1],z0).as_vec3().as_dvec3());hi.push(DVec3::new(p[0],p[1],z1).as_vec3().as_dvec3());}for i in 0..lo.len(){let j=(i+1)%lo.len();self.add_face(&[lo[i],lo[j],hi[j],hi[i]],&[])?;}reverse.extend(lo.into_iter().rev());self.add_face(&reverse,&[])?;self.add_face(&hi,&[])?;Ok(())})();if result.is_err(){self.failed=true;}result}

}
fn face_bound(corners:usize,faces:usize)->Result<usize,String>{corners.checked_mul(2048).and_then(|n|faces.checked_mul(512).and_then(|f|n.checked_add(f))).ok_or_else(||"Face payload overflow".into())}
fn copy_faces(source:&[MeshFace])->Result<Vec<MeshFace>,String>{let mut result=Vec::new();result.try_reserve_exact(source.len()).map_err(|_|"Face history records refused")?;for face in source{if !face.attrs.is_empty()||face.layer.is_some(){return Err("Painted face journal remains open".into());}let mut outer=Vec::new();outer.try_reserve_exact(face.vertices.len()).map_err(|_|"Face history loop refused")?;outer.extend_from_slice(&face.vertices);let mut holes=Vec::new();holes.try_reserve_exact(face.holes.len()).map_err(|_|"Face history holes refused")?;for h in &face.holes{let mut ids=Vec::new();ids.try_reserve_exact(h.len()).map_err(|_|"Face history hole refused")?;ids.extend_from_slice(h);holes.push(ids);}let mut copy=MeshFace::new(outer);copy.holes=holes;copy.interior=face.interior;result.push(copy);}Ok(result)}
fn face_payload(faces:&Vec<MeshFace>,radial:&Vec<(usize,Vec<usize>)>)->Result<usize,String>{let mut bytes=std::mem::size_of::<Command>().checked_add(faces.capacity().checked_mul(std::mem::size_of::<MeshFace>()).ok_or("Face byte overflow")?).ok_or("Face byte overflow")?;for f in faces{bytes=bytes.checked_add(f.vertices.capacity()*8+f.holes.capacity()*std::mem::size_of::<Vec<usize>>()).ok_or("Face byte overflow")?;for h in &f.holes{bytes=bytes.checked_add(h.capacity()*8).ok_or("Face byte overflow")?;}}bytes=bytes.checked_add(radial.capacity()*std::mem::size_of::<(usize,Vec<usize>)>()).ok_or("Radial byte overflow")?;for(_,ids)in radial{bytes=bytes.checked_add(ids.capacity()*8).ok_or("Radial byte overflow")?;}Ok(bytes)}

#[cfg(test)]mod tests{use super::*;
 fn triangle(t:&mut FaceTransaction){t.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[]).unwrap();}
 #[test]fn face_only_command_stales_held_view_and_undo_redo_preserves_radial(){let mut o=FaceOwner::new(Mesh::new()).unwrap();let mut t=o.begin().unwrap();triangle(&mut t);o.commit(t).unwrap();let mut stale=o.begin().unwrap();let mut t=o.begin().unwrap();triangle(&mut t);o.commit(t).unwrap();assert_eq!(o.mesh().vertices.len(),3);assert_eq!(o.mesh().edges.len(),3);assert_eq!(o.mesh().faces.len(),2);assert!(o.mesh().edges.iter().all(|e|e.faces==vec![0,1]));assert!(stale.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[]).is_err());assert!(o.commit(stale).is_err());let saved=o.mesh().clone();o.undo().unwrap();assert!(o.mesh().edges.iter().all(|e|e.faces==vec![0]));o.redo().unwrap();assert_eq!(o.mesh(),&saved);assert_eq!(o.history_counts(),(2,0));}
 #[test]fn two_faces_share_new_edge_in_one_transaction_and_branch_atomically(){let mut o=FaceOwner::new(Mesh::new()).unwrap();let mut t=o.begin().unwrap();triangle(&mut t);t.add_face(&[DVec3::X,DVec3::ZERO,-DVec3::Y],&[]).unwrap();o.commit(t).unwrap();assert_eq!(o.mesh().edges[0].faces,vec![0,1]);assert_eq!(o.history_counts(),(1,0));let saved=o.mesh().clone();o.undo().unwrap();assert!(o.mesh().faces.is_empty());o.redo().unwrap();assert_eq!(o.mesh(),&saved);o.undo().unwrap();let mut t=o.begin().unwrap();triangle(&mut t);o.commit(t).unwrap();assert_eq!(o.history_counts(),(1,0));assert!(!o.redo().unwrap());}
 #[test]fn face_preparation_refusal_preserves_redo_and_earlier_transaction(){let mut o=FaceOwner::new(Mesh::new()).unwrap();let mut t=o.begin().unwrap();triangle(&mut t);o.commit(t).unwrap();o.undo().unwrap();let mut earlier=o.begin().unwrap();let mut candidate=o.begin().unwrap();triangle(&mut candidate);let saved=o.mesh().clone();let budget=o.budget();let before=budget.snapshot();budget.set_limit(Some(before.total()));assert!(o.commit(candidate).is_err());assert_eq!(o.mesh(),&saved);assert_eq!(o.history_counts(),(0,1));budget.set_limit(None);triangle(&mut earlier);o.commit(earlier).unwrap();assert_eq!(o.history_counts(),(1,0));}
 #[test]fn maximal_hole_failure_discards_prior_face_drafts_and_preserves_redo(){let mut o=FaceOwner::new(Mesh::new()).unwrap();let mut t=o.begin().unwrap();triangle(&mut t);o.commit(t).unwrap();o.undo().unwrap();let mut earlier=o.begin().unwrap();let mut t=o.begin().unwrap();triangle(&mut t);assert!(t.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[vec![],vec![DVec3::ZERO,DVec3::X,DVec3::Y]]).unwrap_err().contains("requires three"));assert!(o.commit(t).is_err());assert_eq!(o.history_counts(),(0,1));assert!(o.mesh().vertices.is_empty());triangle(&mut earlier);o.commit(earlier).unwrap();assert_eq!(o.history_counts(),(1,0));}
 #[test]fn degenerate_face_membership_once_and_free_edge_refusal_remains_source_owned(){let mut o=FaceOwner::new(Mesh::new()).unwrap();let mut t=o.begin().unwrap();t.add_face(&[DVec3::ZERO],&[]).unwrap();o.commit(t).unwrap();assert_eq!(o.mesh().vertices[0].edges,vec![0]);assert_eq!(o.mesh().edges[0].faces,vec![0]);let mut reloaded=FaceOwner::new(o.mesh().clone()).unwrap();let mut t=reloaded.begin().unwrap();t.add_face(&[DVec3::ZERO,DVec3::X],&[]).unwrap();reloaded.commit(t).unwrap();assert_eq!(reloaded.mesh().edges[1].faces,vec![1,1]);let saved=reloaded.mesh().clone();reloaded.undo().unwrap();assert_eq!(reloaded.mesh().vertices[0].edges,vec![0]);reloaded.redo().unwrap();assert_eq!(reloaded.mesh(),&saved);let mut edge=reloaded.owner.begin();assert!(edge.add_edge(DVec3::ZERO,DVec3::ZERO).unwrap_err().contains("degenerate edge"));assert!(!reloaded.owner.commit(edge).unwrap());}
 #[test]fn caught_face_refusal_never_publishes_prior_drafts(){let mut o=FaceOwner::new(Mesh::new()).unwrap();let budget=o.budget();let mut t=o.begin().unwrap();triangle(&mut t);assert!(t.add_face(&[DVec3::ZERO,DVec3::NAN,DVec3::X],&[]).is_err());assert!(o.commit(t).is_err());assert!(o.mesh().faces.is_empty());assert!(o.mesh().vertices.is_empty());assert_eq!(o.history_counts(),(0,0));assert_eq!(budget.snapshot().total(),0);}
 #[test]fn existing_edge_metadata_survives_face_radial_append_and_history(){let mut m=Mesh::new();let a=m.add_vertex(DVec3::ZERO);let b=m.add_vertex(DVec3::X);let eid=m.add_edge(a,b).unwrap();m.edges[eid].soft=true;m.edges[eid].hidden=true;m.edges[eid].layer=Some("Authored".into());m.edges[eid].attrs.insert("opaque_vendor".into(),serde_json::json!({"nested":[1,"two"]}));let old=m.edges[eid].clone();let mut o=FaceOwner::new(m).unwrap();let mut t=o.begin().unwrap();triangle(&mut t);o.commit(t).unwrap();let painted=o.mesh().clone();o.undo().unwrap();assert_eq!(o.mesh().edges[eid],old);o.redo().unwrap();assert_eq!(o.mesh(),&painted);}
 #[test]fn new_radial_byte_refusal_precedes_edge_publication(){let mut o=FaceOwner::new(Mesh::new()).unwrap();let mut t=o.begin().unwrap();triangle(&mut t);let budget=o.budget();let baseline=budget.snapshot();let face=MeshFace::new(vec![0,1,2]);let radial=(0..3).map(|id|{let mut ids=Vec::with_capacity(4);ids.push(0);(id,ids)}).collect();let history=face_payload(&vec![face],&radial).unwrap();budget.set_limit(Some(baseline.total()+face_bound(3,1).unwrap()+history));let error=o.commit(t).unwrap_err();assert!(error.contains("New radial preparation"),"{error}");assert_eq!(o.history_counts(),(0,0));assert!(o.mesh().vertices.is_empty());assert!(o.mesh().edges.is_empty());assert!(o.mesh().faces.is_empty());assert_eq!(budget.snapshot().total(),0);budget.set_limit(None);let mut t=o.begin().unwrap();triangle(&mut t);assert!(o.commit(t).unwrap());}
}
